using System.ComponentModel;
using ModelContextProtocol.Server;

namespace McpHttpServer.Resources;

[McpServerResourceType]
public static class ConfigResources
{
    /// <summary>Returns global application configuration.</summary>
    [McpServerResource(UriTemplate = "config://app",
        Name = "app-config",
        MimeType = "application/json")]
    [Description("Returns the current application configuration.")]
    public static string GetAppConfig()
    {
        return """
            {
                "environment": "Production",
                "version": "1.0.0",
                "features": {
                    "darkMode": true,
                    "maxRetries": 3
                }
            }
            """;
    }

    /// <summary>Returns per-user settings by user ID.</summary>
    [McpServerResource(UriTemplate = "config://users/{userId}",
        Name = "user-settings",
        MimeType = "application/json")]
    [Description("Returns configuration for a specific user.")]
    public static string GetUserSettings(string userId)
    {
        return $$"""
            {
                "userId": "{{userId}}",
                "theme": "dark",
                "language": "en-US",
                "notifications": true
            }
            """;
    }
}

