toolArgs.old_str:
using McpHttpServer.Tools;
using ModelContextProtocol;
using ModelContextProtocol.Server;

var builder = WebApplication.CreateBuilder(args);

builder.Services
    .AddMcpServer()
    .WithHttpTransport()
    .WithTools<EchoTool>()
    .WithResources(resources =>
    {
        // Static resource: application configuration data
        resources.AddResource("config://app", "Application Config", "application/json",
            "Returns the current application configuration.",
            async (uri, cancellationToken) => $"""
            {{
                "environment": "{builder.Environment.EnvironmentName}",
                "version": "1.0.0",
                "features": {{
                    "darkMode": true,
                    "maxRetries": 3
                }}
            }}
            """);

        // Resource template: per-user settings
        resources.AddResourceTemplate("config://users/{userId}", "User Settings", "application/json",
            "Returns configuration for a specific user.",
            async (parameters, uri, cancellationToken) =>
            {
                var userId = parameters["userId"];
                return $"""
                {{
                    "userId": "{userId}",
                    "theme": "dark",
                    "language": "en-US",
                    "notifications": true
                }}
                """;
            });
    });

var app = builder.Build();

app.MapMcp();

app.Run();

